 const normal=group('流程',12)+'<button type="button" class="tree-folder" data-go="workspace">'+icon('down',12)+icon('folder',15)+'常用流程<span>4</span></button>'+item('flow','月度报表下载','editor-graph','12',true,'indent')+item('flow','账单附件整理','editor-graph','7',false,'indent')+item('flow','批量数据录入','editor-graph','4',false,'indent')+item('flow','截图巡检','editor-graph','3',false,'indent')+'<div class="side-section-gap"></div>'+group('固定依赖',2)+item('image','下载按钮','asset-image','v3',false,'dependency')+item('flow','校验下载结果','editor-steps','v2',false,'dependency')+'<button type="button" class="side-add-resource" data-go="assets">'+icon('plus',14)+'添加资源</button><div class="side-section-gap"></div>'+group('制作工具','')+item('record','录制桌面操作','record-config')+item('image','批量制作模板','templates-source')+item('eye','视觉观察中心','observations-center');
