 return '<aside class="project-sidebar premium-sidebar"><div class="project-identity"><span class="project-avatar">'+icon('folder',18)+'</span><div><strong>个人自动化</strong><span><i></i>本地工作空间</span></div>'+iconBtn('more','工作空间操作','workspace')+'</div><div class="sidebar-switch"><button type="button" class="'+(!library?'active':'')+'" data-go="editor-graph">流程与资源</button><button type="button" class="'+(library?'active':'')+'" data-go="action-library">动作库</button></div>'+search(library?'搜索动作':'查找流程或资源')+'<div class="sidebar-content">'+(library?libraryBody:normal)+'</div><div class="sidebar-footer"><div class="side-storage"><span>'+icon('database',14)+'工作空间存储</span><strong>128 MB</strong></div><div class="side-storage-track"><i></i></div><div class="between"><small>28 份资产 · 12 个流程</small>'+iconBtn('settings','存储与备份','settings-storage')+'</div></div></aside>';
