 const items=[['下载按钮','模板','v3','image','126 × 40 px','3 个流程引用','今天 09:36'],['下载完成提示','模板','v2','image','164 × 42 px','2 个流程引用','昨天 16:20'],['归档快捷操作','轨迹','v4','mouse','32 个事件 · 1.6 秒','4 个流程引用','昨天 14:12'],['表单提交按钮','模板','v1','image','108 × 38 px','1 个流程引用','10月27日'],['窗口切换序列','轨迹','v2','keyboard','18 个事件 · 0.9 秒','2 个流程引用','10月26日'],['确认对话框','模板','v2','image','236 × 112 px','2 个流程引用','10月25日']];
